mapper.select:

WHERE st.deleted = 0

    AND (st.stu_no LIKE CONCAT('%', #{keyword}, '%')
    OR su.real_name LIKE CONCAT('%', #{keyword}, '%')
    OR st.class_name LIKE CONCAT('%', #{keyword}, '%'))


    AND st.dept_id = #{deptId}


    AND st.major_id = #{majorId}


    AND st.grade_year = #{gradeYear}

ORDER BY st.stu_no ASC
